package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUkDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Суббухун Куддус (Руку та Суджуд)", "(Аллах) Найпрославленіший, Найсвятіший, Господь ангелів і Духа (Джібріл).", "У руку і суджуд.", "Пророк ﷺ прочитав це на руку та суджуд."),
        "dua_sujood_dhanbi_kullah" to DuaText("У Суджуді: Прости всі мої гріхи", "О Аллах, прости мені всі мої гріхи — малі й великі, перші й останні, явні й приховані.", "У суджуді.", "Прострація - це місце, де відповідають на дуа."),
        "dua_sujood_ridaka" to DuaText("Притулок у вашій насолоді", "O Allah, I seek refuge in Your pleasure from Your anger, in Your pardon from Your punishment, and I seek refuge in You from You. Я не можу повністю хвалити Тебе; Ти такий, як Сам себе хвалив.", "У суджуді — Айша (RA) почула, як Пророк ﷺ сказав це.", "Суджуд дуа Пророка ﷺ."),
        "dua_tashahhud" to DuaText("Ташаххуд (Ат-Тахійят)", "Усі вербальні, фізичні та фінансові акти поклоніння Аллаху. Мир тобі, о Пророк, і милість Аллаха та Його благословення. Мир нам і праведним рабам Аллаха. Я свідчу, що ніхто не гідний поклоніння, крім Аллаха, і я свідчу, що Мухаммад ﷺ є Його слугою і Посланцем.", "У кожному присіданні — передано Абдуллою ібн Масудом (RA) (ханафітська практика).", "Пророк ﷺ викладав його як суру Корану."),
        "dua_sajdah_tilawah" to DuaText("Саджда декламації", "Моє обличчя поклонилося Тому, Хто створив його і дав йому слух і зір Своєю могутністю та силою.", "У прострації декламація.", "Пророк ﷺ сказав це під час прострації читання вночі."),
        "dua_after_witr" to DuaText("Після Вітр", "Слава Царю Пресвятому.", "Тричі після саляму вітр, підвищення голосу втретє.", "Пророк ﷺ сказав це після витр."),
        "dua_tahajjud_nur" to DuaText("Тахаджуд Вступна молитва", "О Аллах, Тобі належить хвала; Ти – Творець небес, землі і всього, що в них. Тобі належить хвала; Ти є Світло небес, землі і всього, що в них. Тобі належить хвала; Ти — Істина, Твоя обітниця — істинна, зустріч з Тобою — істина, Твоє слово — істина, Рай — істина, Пекло — істина, Пророки — істина, Мухаммад ﷺ — істинно, Година — істинно.", "На початку нічної молитви (тахаджуд) (початкова частина дуа).", "Пророк ﷺ прочитав це, коли вставав для тахаджуду (повна дуа є в аль-Бухарі)."),
        "dua_rabba_jibrail" to DuaText("Поведи мене в спірних справах", "О Аллах, Господь Джибріла, Мікаїла та Ісрафіла, Творець небес і землі, Знавець невидимого і видимого! Ти розсудиш Своїх рабів за тим, чим вони відрізнялися. Проведи мене Твоїм дозволом до істини в тому, у чому були розбіжності. Воістину, кого хочеш, Ти направляєш на прямий шлях.", "На початку тахаджуду — для наставлення до істини серед розбіжностей.", "Пророк ﷺ почав свою нічну молитву з цієї дуа."),
        "dua_going_to_mosque_nur" to DuaText("Перехід до мечеті (дуа світла)", "О Аллах, поклади світло в моє серце, світло в мої очі, світло в мої вуха, світло праворуч від мене, світло ліворуч від мене, світло наді мною, світло піді мною, світло переді мною, світло позаду мене, і зроби світло для мене.", "Під час збирання в мечеть на Фаджр.", "Пророк ﷺ прочитав це, коли виходив на молитву."),
        "dua_waswasa_salah" to DuaText("Васваса під час Салаха (Хінзаб)", "Я шукаю притулку в Аллаха від шайтана, проклятого.", "Коли під час молитви лунає сатанинський шепіт, знайдіть притулок і тричі злегка плюньте вліво.", "Осман ібн Абіль-'Ас (RA) зробив це, і шепіт зник."),
        "dua_alimal_ghayb" to DuaText("Знавець Невидимого", "О Аллах, Знавець невидимого і видимого, Творець небес і землі, Господь і Володарю всього сущого! Я свідчу, що немає Бога, крім Тебе. Я шукаю притулку в Тебе від власного зла, а також від зла Шайтана та його (заклику до) ухилення.", "Вранці, ввечері та перед сном — Пророк ﷺ навчив цьому Абу Бакра (RA).", "Захист від зла себе і шайтана."),
        "dua_fitratil_islam" to DuaText("Про фітру ісламу", "Ми увійшли в ранок згідно з фітрою ісламу, словом щирості, релігією нашого пророка Мухаммада ﷺ і шляхом нашого батька Ібрагіма (AS), який був праведним і мусульманином, і не належав до багатобожників.", "Вранці.", "Щоранку відновлювати свою віру."),
        "dua_amsayna_fitrah" to DuaText("Вечір на Фітру ісламу", "Ми увійшли в вечір згідно з фітрою ісламу, словом щирості, релігією нашого пророка Мухаммада ﷺ і шляхом нашого батька Ібрагіма (AS), який був праведним і мусульманином, і не належав до політеїстів.", "Увечері.", "Відновлення віри щовечора."),
        "dua_tahleel_10_fajr" to DuaText("Десять талілів після Фаджру та Магрібу", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Його панування і Його хвала; Він дає життя і спричиняє смерть, і Він має владу над усім.", "Десять разів після Фаджру (і Магрібу), перш ніж перестати сидіти або говорити.", "Десять добрих справ, десять стертих гріхів, десять рангів підвищених і захист від шайтана весь день."),
        "dua_la_hawla_kanz" to DuaText("Скарб Джанни", "Немає ніякої могутності та влади, окрім Аллаха.", "Часто, завжди.", "Це один із скарбів Раю."),
        "dua_four_beloved_words" to DuaText("Чотири найулюбленіші слова", "Слава Аллаху, вся хвала Аллаху, ніхто не гідний поклоніння, крім Аллаха, і Аллах є найбільшим.", "Слова, найулюбленіші для Аллаха.", "Вони дорожчі Пророку ﷺ за все, над чим сходить сонце."),
        "dua_two_light_words" to DuaText("Два слова легкі на язиці", "Слава Аллаху і вся хвала Йому; слава Аллаху, Всевеличному.", "Легкий на язиці, важкий на шкалі.", "Улюблений Всемилостивому, легкий на язиці і важкий на Терезах. (Останній хадис аль-Бухарі)"),
        "dua_ya_dhal_jalal" to DuaText("Я Дхал-Джалалі валь-Ікрам", "О Володарю величі й честі!", "Тримайся за це в дуа — інструкція Пророка ﷺ.", "Пророк ﷺ сказав: тримайтеся «Я Дал-Джалалі валь-Ікрам»."),
        "dua_sleep_wadatu_janbi" to DuaText("В Ім'я Твоє я лягаю", "В ім’я Твоє, Господи мій, я лягаю на бік і в ім’я Твоє я встаю. Якщо Ти візьмеш мою душу, змилуйся над нею, а якщо відпустиш її, то захисти її, як Ти захистив праведних рабів Твоїх.", "Витерши пил з ліжка і лягти.", "Довірити свою душу Аллаху перед сном."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Ти створив мою душу", "О Аллах, Ти створив мою душу і Ти візьмеш її. Його смерть і його життя належать Тобі. Якщо Ти зберігаєш його живим, захисти його, а якщо Ти змушуєш його померти, прости йому. О Аллах, я прошу Тебе про благополуччя.", "Перед сном — передано Ібн Умаром (RA).", "Пророк ﷺ наказав говорити це перед сном."),
        "dua_sleep_atamana" to DuaText("Подяка перед сном", "Вся хвала Аллаху, який нас нагодував, напоїв, наситив нас і дав нам притулок. Скільки є тих, хто не має нікого, хто б їх вигодував або дав притулок.", "Коли лягати спати.", "Пророк ﷺ сказав це, лягаючи спати."),
        "dua_sleep_rabbas_samawat" to DuaText("Володар небес — сплати наш борг", "О Аллах, Владико небес, землі і Могутнього Престолу, наш Владико і Владико всього сущого, Розділювач насіння і фінікового каменю, Відкриватель Тори, Інджила і Фуркана! Я шукаю притулку в Тебе від зла всього, чиє чуба Ти тримаєш. О Аллах, Ти Перший, немає нічого перед Тобою; Ти останній, після тебе нічого немає; Ти — Маніфест, над Тобою немає нічого; Ти — Прихований, від Тебе немає нічого прихованого. Погасіть наш борг за нас і звільніть нас від бідності.", "Перед сном лежачи на правому боці — вчили Фатіму (RA).", "Дуа для звільнення від боргів і труднощів."),
        "dua_sleep_fear" to DuaText("Страх або неспокій уві сні", "Я шукаю притулку в досконалих словах Аллаха від Його гніву та Його покарання, від зла Його рабів, від шепоту дияволів і від їх приходу до мене.", "Коли ви відчуваєте страх або неспокій уві сні.", "Зробивши це, ця річ не зашкодить йому."),
        "dua_waking_afani" to DuaText("Пробудження: Він відновив мою душу", "Вся хвала Аллаху, який дав моєму тілу благополуччя, повернув мені мою душу і дозволив мені згадувати Його.", "При пробудженні.", "Подяка за новий ранок."),
        "dua_allahu_rabbi" to DuaText("Аллах, Аллах - мій Господь", "Аллах, Аллах - мій Господь; Я нічого не асоціюю з Ним.", "У горі чи біді — Пророк ﷺ навчив цьому Асму бінт Умайс (RA).", "Тримаючись за тавхід у важкі часи."),
        "dua_rahmataka_arju" to DuaText("Ваше милосердя, на яке я сподіваюся", "О Аллах, я сподіваюся на Твою милість, тож не залишай мене самому навіть на мить ока, і виправляй усі мої справи. Немає Бога, крім Тебе.", "Дуа того, хто в біді (Da'awat al-makrub).", "Пророк ﷺ назвав це дуа того, хто в біді."),
        "dua_against_enemy_ahzab" to DuaText("Проти армій ворога", "О Аллах, Відкриватель Книги, Швидкий у розплаті! Перемогти конфедератів. О Аллах, переможи їх і потряси їх.", "Проти ворога — дуа Битви Конфедератів.", "Дуа Пророка ﷺ проти ворога."),
        "dua_anta_adudi" to DuaText("Ти моя опора", "О Аллах, Ти моя опора і мій помічник. Завдяки Тобі я планую, завдяки Тобі я наступаю і завдяки Тобі я борюся.", "Перед змаганням або серйозним викликом.", "Пророк ﷺ сказав це в битві."),
        "dua_ikfinihim" to DuaText("Досить мене проти них", "О Аллах, вистачи мене проти них, як забажаєш.", "Проти зла гнобителів — дуа хлопця в повісті «Люди рову».", "Аллах врятував хлопчика від гнобителів."),
        "dua_qadarullah" to DuaText("Коли трапляється щось погане", "Це розпорядження Аллаха, і Він зробив те, що хотів.", "Коли трапляється щось неприємне, замість того, щоб говорити «якби».", "«Якби тільки» відкриває двері до Шайтана."),
        "dua_ala_kulli_hal" to DuaText("Хвала в будь-якій ситуації", "Вся хвала Аллаху в кожній ситуації.", "Коли трапляється щось неприємне.", "Пророк ﷺ сказав це, зіткнувшись з тим, що йому не подобається."),
        "dua_dogs_barking" to DuaText("Чути гавкіт собак вночі", "Я шукаю притулку в Аллаха від шайтана, проклятого.", "Почувши вночі собаки гавкають або осел реве.", "Вони бачать те, чого ви не бачите."),
        "dua_leaving_home_adilla" to DuaText("Притулок від помилкового шляху", "О Аллах, я шукаю притулку в Тебе, щоб я не збився з шляху або не був зведений зі шляху, щоб я не помилився або не був змушений помилитися, щоб я не вчинив неправильно або не зазнав кривди, щоб я не поводився нерозумно або щоб зі мною поводилися нерозумно.", "Виходячи з дому — розповідає Умм Салама (RA).", "Пророк ﷺ читав це щоразу, коли виходив із дому."),
        "dua_ascending_descending" to DuaText("Підйом і спуск", "Аллах є найбільшим (коли піднімається). — Слава Аллаху (при спуску).", "Під час подорожі скажіть «Аллаху Акбар», коли піднімаєтеся, і «СубханАллах», коли спускаєтеся.", "Практика сподвижників (RA) під час подорожі."),
        "dua_traveller_sahar" to DuaText("Дуа мандрівника перед світанком", "Слухач почув (і передав) нашу хвалу Аллаху та Його благодаті до нас. Господи наш, супроводжуй нас і даруй нам Свою милість — (я кажу це), шукаючи притулку в Аллаха від Вогню.", "В дорозі, до світанку.", "Пророк ﷺ сказав це перед світанком під час подорожі."),
        "dua_zawwadakallah" to DuaText("Мандрівнику: Нехай Аллах дарує такву", "Нехай Аллах дасть вам такву для вашої подорожі, пробачить ваші гріхи і зробить для вас усе благополуччя, де б ви не були.", "При прощанні з подорожнім.", "Пророк ﷺ дав цю дуа тому, хто вирушає в подорож."),
        "dua_traveller_to_resident" to DuaText("Мандрівник до тих, хто залишився позаду", "Я доручаю тебе Аллаху, довіра до якого ніколи не втрачається.", "Сказане мандрівником, прощаючись із родиною.", "Довірити безпеку сім'ї Аллаху."),
        "dua_entering_village" to DuaText("В'їзд у місто чи село", "О Аллах, Господь семи небес і всього, що вони затінюють, Господь семи земель і всього, що вони несуть, Господь дияволів і всього, що вони вводять в оману, Господь вітрів і всього, що вони розсіюють! Ми просимо Тебе про добро цього міста і добра його людей, і ми шукаємо притулку в Тебе від його зла, зла його людей і зла того, що в ньому є.", "Перед в'їздом у місто.", "Пророк ﷺ читав це щоразу, коли хотів увійти в місто."),
        "dua_vehicle_stumbles" to DuaText("Коли транспортний засіб спотикається", "В ім'я Аллаха.", "Коли скакун або транспортний засіб ковзає або спотикається, замість того, щоб сказати «Хай загине Шайтан».", "Вимовляючи Bismillah, Шейтан зменшується до розміру мухи."),
        "dua_ajz_kasal_haram" to DuaText("Притулок від слабкості та старості", "О Аллах, я вдаюся до Тебе від безсилля і лінощів, від боягузтва і старості, від випробувань життя і смерті і від кари могили.", "Повний щоденний дуа притулку.", "Дуа, яку Пророк ﷺ вимовляв часто."),
    )
}
